import { useEffect, useState } from "react";

export default function UserName({ id, loadUser }) {
  const [result, setResult] = useState({ id, status: "loading", name: "", error: "" });
  useEffect(() => {
    let active = true;
    loadUser(id).then(
      user => { if (active) setResult({ id, status: "ready", name: user.name, error: "" }); },
      () => { if (active) setResult({ id, status: "error", name: "", error: "Unable to load" }); }
    );
    return () => { active = false; };
  }, [id, loadUser]);
  if (result.id !== id || result.status === "loading") return <p>Loading</p>;
  if (result.error) return <p role="alert">{result.error}</p>;
  return <p>{result.name}</p>;
